// illustrative monitoring snippet, built on the public API
function deadLetterRateByChannel(scheduler: SocialScheduler): Record<string, number> {
  const terminal: Record<string, { dead: number; total: number }> = {};
  for (const post of scheduler.list()) {
    for (const d of Object.values(post.deliveries)) {
      if (d.status !== "sent" && d.status !== "dead_letter") continue;
      terminal[d.channel] ??= { dead: 0, total: 0 };
      terminal[d.channel]!.total++;
      if (d.status === "dead_letter") terminal[d.channel]!.dead++;
    }
  }
  return Object.fromEntries(Object.entries(terminal).map(([c, v]) => [c, v.dead / v.total]));
}

