function dueBacklog(scheduler: SocialScheduler, now: number): { channel: string; staleMs: number }[] {
  const stuck: { channel: string; staleMs: number }[] = [];
  for (const post of scheduler.list()) {
    for (const d of Object.values(post.deliveries)) {
      if (d.status === "pending" && d.nextAttemptAt <= now) {
        stuck.push({ channel: d.channel, staleMs: now - d.nextAttemptAt });
      }
    }
  }
  return stuck;
}

