async function workerTick(queue: JobQueue, scheduler: SocialScheduler, leaseMs: number): Promise<void> {
  const jobs = queue.claim(Date.now(), 50, leaseMs); // channels due, claimed with a lease token
  await Promise.all(jobs.map(async (job) => {
    const result = await dispatchOneChannel(scheduler, job.postId, job.channel); // reuses dispatchChannel's core logic
    if (queue.owns(job.id, job.leaseToken, Date.now())) {
      result.terminal ? queue.complete(job.id, job.leaseToken, Date.now()) : queue.reschedule(job.id, job.leaseToken, result.nextAttemptAt, Date.now());
    } // else: lease expired, another worker already reclaimed it -- discard this result
  }));
}

