function worstCaseTicksToTerminal(maxAttempts: number): number {
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) {
    throw new RangeError("maxAttempts must be an integer >= 1");
  }
  // backoffMs only determines WHEN the next tick() must happen (the clock-advance amount),
  // never HOW MANY tick() calls are needed -- each due tick() consumes exactly one attempt.
  return maxAttempts;
}

