describe("cancel mid-retry", () => {
  it("canceling a channel mid-retry stops every future dispatch attempt for it", async () => {
    const NOW = Date.UTC(2026, 10, 28, 9, 0);
    const clock = new ManualClock(NOW);
    const mastodon = new AlwaysFailsProvider("instance down");
    const scheduler = new SocialScheduler({
      providers: { mastodon }, clock, maxAttempts: 5, initialBackoffMs: 1000, maxBackoffMs: 60_000,
    });
    const post = scheduler.schedulePost({
      clientRequestId: "r1", content: "hi", channels: ["mastodon"], scheduledAt: NOW,
    });

    await scheduler.tick(); // attempt 1 fails, still pending, awaiting retry
    expect(mastodon.attempts).toHaveLength(1);

    scheduler.cancelChannel(post.id, "mastodon"); // canceled mid-retry (attempts > 0)

    clock.advance(10 * 60 * 60_000); // advance far past any backoff window
    await scheduler.tick();
    expect(mastodon.attempts).toHaveLength(1); // no further provider calls, ever
    expect(scheduler.getPost(post.id)!.deliveries.mastodon!.status).toBe("canceled");
  });
});

