import type { SocialScheduler } from "./src/scheduler.js";

interface DeadLetterRow { postId: string; channel: string; attempts: number; lastError?: string }
export interface DeadLetterReport { early: DeadLetterRow[]; exhausted: DeadLetterRow[] }

export function classifyDeadLetters(scheduler: SocialScheduler): DeadLetterReport {
  const report: DeadLetterReport = { early: [], exhausted: [] };
  for (const post of scheduler.list()) {
    for (const d of Object.values(post.deliveries)) {
      if (d.status !== "dead_letter") continue;
      const row = { postId: post.id, channel: d.channel, attempts: d.attempts, lastError: d.lastError };
      if (d.attempts < d.maxAttempts) report.early.push(row); // only a retryable: false failure stops early
      else report.exhausted.push(row); // retries ran out -- OR a permanent failure on the last attempt
    }
  }
  return report;
}

